.libPaths(unique(c('/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.5','/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.4',.libPaths())))
suppressPackageStartupMessages({library(data.table);library(qs)})
root<-'/home/data/t070721/codex_workspace/Bladder Metabolism/mp10_subtype_screen_round1_v2';tt<-file.path(root,'tables');s<-fread(file.path(tt,'samples_v2.tsv'));s[,score_coverage_trusted:=tolower(as.character(score_coverage_trusted))=='true'];d<-fread(file.path(tt,'B_Plasma_LR_contrasts.tsv.gz'));d<-d[comparison_type=='epi_state_within_specimen'&(status_low=='detected'|status_high=='detected')];cand<-unique(d[,.(network_level,TME_type,direction,LR_id,ligand,receptor,ligand_genes,receptor_genes,MP10_gene_overlap)]);rows<-list();gene_rows<-list()
for(lev in c('major','fine')){o<-qread(file.path(root,'objects',paste0('expression_',lev,'.qs')));meta<-o$metadata;aa<-cand[network_level==lev]
 getval<-function(gs,key){gi<-match(gs,rownames(o$mean));j<-match(key,colnames(o$mean));if(anyNA(gi)||is.na(j))return(c(mean=NA_real_,detection=NA_real_));vv<-as.numeric(o$mean[gi,j]);c(mean=if(any(vv==0))0 else exp(mean(log(vv))),detection=min(as.numeric(o$detection[gi,j])))}
 for(k in seq_len(nrow(aa))){a<-aa[k];eg<-strsplit(if(a$direction=='epi_to_TME')a$ligand_genes else a$receptor_genes,';',fixed=TRUE)[[1]];tg<-strsplit(if(a$direction=='epi_to_TME')a$receptor_genes else a$ligand_genes,';',fixed=TRUE)[[1]]
 for(i in seq_len(nrow(s))){sp<-s[i];keys<-paste(sp$sample_uid,c('Epi_MP10_low','Epi_MP10_high',a$TME_type),sep='|||');nn<-meta$n_cells[match(keys,meta$aggregate_id)];eligible<-length(nn)==3&&all(is.finite(nn))&&all(nn>=30)&&sp$score_coverage_trusted
 vl<-getval(eg,keys[1]);vh<-getval(eg,keys[2]);vt<-getval(tg,keys[3]);rs<-cbind(a,data.table(sample_uid=sp$sample_uid,dataset=sp$dataset,patient_uid_recorded=sp$patient_uid_recorded,n_epi_low=nn[1],n_epi_high=nn[2],n_target=nn[3],coverage_eligible=eligible,epi_low_mean=vl[1],epi_high_mean=vh[1],target_mean=vt[1],epi_low_detection=vl[2],epi_high_detection=vh[2],target_detection=vt[2],low_supported=vl[2]>=.1&&vt[2]>=.1,high_supported=vh[2]>=.1&&vt[2]>=.1,epi_delta=vh[1]-vl[1],aux_product_low=vl[1]*vt[1],aux_product_high=vh[1]*vt[1],aux_product_delta=(vh[1]-vl[1])*vt[1]));rows[[length(rows)+1]]<-rs
 if(eligible)for(j in 1:3){gs<-if(j<3)eg else tg;for(g in gs){v<-getval(g,keys[j]);gene_rows[[length(gene_rows)+1]]<-cbind(a[,.(network_level,TME_type,direction,LR_id)],data.table(sample_uid=sp$sample_uid,dataset=sp$dataset,patient_uid_recorded=sp$patient_uid_recorded,node=c('Epi_MP10_low','Epi_MP10_high',a$TME_type)[j],gene=g,mean=v[1],detection=v[2],measured=is.finite(v[1])))}}
 }}}
r<-rbindlist(rows);fwrite(r,file.path(tt,'candidate_sample_expression.tsv.gz'),sep='\t',na='NA');fwrite(rbindlist(gene_rows),file.path(tt,'candidate_gene_expression.tsv.gz'),sep='\t',na='NA');cat('DONE',nrow(r),'sample LR rows\n')
